39: public class DefaultSessionAdapter implements SessionAdapter {
40: 
41:   private final Map<String, String> strings = Maps.newHashMap();
42:   private final Map<Class<?>, byte[]> objects = Maps.newHashMap();
43: 
44:   private final SessionId sessionId;
45:   private final ByteBufAllocator bufferAllocator;
46:   private final SessionStoreAdapter storeAdapter;
47:   private final SessionStatus status;
48:   private final SessionValueSerializer defaultSerializer;
49: 
50:   boolean needsLoad = true;
51:   private final SyncSession sync = new Sync();
52: 
53:   private static class Data implements Serializable {
54:     Map<String, String> strings;
55:     Map<Class<?>, byte[]> objects;
56: 
57:     public Data(Map<String, String> strings, Map<Class<?>, byte[]> objects) {
58:       this.strings = strings;
59:       this.objects = objects;
60:     }
61:   }
62: 
63:   public DefaultSessionAdapter(SessionId sessionId, ByteBufAllocator bufferAllocator, SessionStoreAdapter storeAdapter, SessionStatus sessionStatus, SessionValueSerializer defaultSerializer) {
64:     this.sessionId = sessionId;
65:     this.bufferAllocator = bufferAllocator;
66:     this.storeAdapter = storeAdapter;
67:     this.status = sessionStatus;
68:     this.defaultSerializer = defaultSerializer;
69:   }
70: 
71:   @Override
72:   public Promise<SyncSession> getSync() {
73:     if (needsLoad) {
74:       return storeAdapter.load(sessionId, bufferAllocator).map(data -> {
75:         needsLoad = false;
76:         try {
77:           hydrate(data);
78:         } finally {
79:           data.release();
80:         }
81:         return sync;
82:       });
83:     } else {
84:       return execControl().promiseOf(sync);
85:     }
86:   }
87: 
88:   private void hydrate(ByteBuf data) {
89:     if (data.readableBytes() > 0) {
90:       try {
91:         Data deserializedData = defaultSerializer.deserialize(Data.class, new ByteBufInputStream(data));
92:         this.strings.clear();
93:         this.strings.putAll(deserializedData.strings);
94:         this.objects.clear();
95:         this.objects.putAll(deserializedData.objects);
96:         status.setDirty(false);
97:       } catch (Exception e) {
98:         throw Exceptions.uncheck(e);
99:       }
100:     }
101:   }
102: 
103: 
104:   @Override
105:   public boolean isDirty() {
106:     return status.isDirty();
107:   }
108: 
109:   private ByteBuf serialize() {
110:     Data data = new Data(ImmutableMap.copyOf(strings), ImmutableMap.copyOf(objects));
111:     ByteBuf buffer = bufferAllocator.buffer();
112:     OutputStream outputStream = new ByteBufOutputStream(buffer);
113:     try {
114:       defaultSerializer.serialize(Data.class, data, outputStream);
115:       outputStream.close();
116:       return buffer;
117:     } catch (Throwable e) {
118:       buffer.release();
119:       throw Exceptions.uncheck(e);
120:     }
121:   }
122: 
123:   @Override
124:   public Operation save() {
125:     return storeAdapter.store(sessionId, bufferAllocator, serialize())
126:       .next(() -> {
127:         status.setDirty(false);
128:       });
129:   }
130: 
131:   @Override
132:   public Operation terminate() {
133:     return storeAdapter.remove(sessionId)
134:       .next(() -> {
135:         sessionId.terminate();
136:         hydrate(Unpooled.buffer(0, 0));
137:       });
138:   }
139: 
140:   private void markDirty() {
141:     status.setDirty(true);
142:   }
143: 
144:   private class Sync implements SyncSession {
145: 
146:     @Override
147:     public Optional<String> get(String key) {
148:       return Optional.ofNullable(strings.get(key));
149:     }
150: 
151:     @Override
152:     public <T> Optional<? extends T> get(Class<T> key) {
153:       return get(key, defaultSerializer);
154:     }
155: 
156:     @Override
157:     public <T> Optional<? extends T> get(Class<T> key, SessionValueSerializer serializer) {
158:       byte[] bytes = objects.get(key);
159:       if (bytes == null) {
160:         return Optional.empty();
161:       } else {
162:         try {
163:           return Optional.of(serializer.deserialize(key, new ByteArrayInputStream(bytes)));
164:         } catch (IOException e) {
165:           throw Exceptions.uncheck(e);
166:         }
167:       }
168:     }
169: 
170:     @Override
171:     public void set(String key, String value) {
172:       markDirty();
173:       strings.put(key, value);
174:     }
175: 
176:     @Override
177:     public <T> void set(Class<T> key, T value) {
178:       set(key, value, defaultSerializer);
179:     }
180: 
181:     @Override
182:     public <T> void set(Class<T> key, T value, SessionValueSerializer serializer) {
183:       Objects.requireNonNull(key, "session key cannot be null");
184:       Objects.requireNonNull(value, "session value for key " + key.getName() + " cannot be null");
185: 
186:       ByteArrayOutputStream out = new ByteArrayOutputStream();
187:       try {
188:         serializer.serialize(key, value, out);
189:       } catch (IOException e) {
190:         throw Exceptions.uncheck(e);
191:       }
192: 
193:       objects.put(key, out.toByteArray());
194:       markDirty();
195:     }
196: 
197:     @Override
198:     public <T> void set(T value) {
199:       set(value, defaultSerializer);
200:     }
201: 
202:     @Override
203:     public <T> void set(T value, SessionValueSerializer serializer) {
204:       Class<T> type = Types.cast(value.getClass());
205:       set(type, value, serializer);
206:     }
207: 
208:     @Override
209:     public Set<String> getStringKeys() {
210:       return strings.keySet();
211:     }
212: 
213:     @Override
214:     public Set<Class<?>> getTypeKeys() {
215:       return objects.keySet();
216:     }
217: 
218:     @Override
219:     public void remove(String key) {
220:       strings.remove(key);
221:       markDirty();
222:     }
223: 
224:     @Override
225:     public <T> void remove(Class<T> key) {
226:       objects.remove(key);
227:       markDirty();
228:     }
229: 
230:     @Override
231:     public void clear() {
232:       strings.clear();
233:       objects.clear();
234:       markDirty();
235:     }
236: 
237:     @Override
238:     public boolean isDirty() {
239:       return DefaultSessionAdapter.this.isDirty();
240:     }
241: 
242:     @Override
243:     public Operation save() {
244:       return DefaultSessionAdapter.this.save();
245:     }
246: 
247:     @Override
248:     public Operation terminate() {
249:       return DefaultSessionAdapter.this.terminate();
250:     }
251:   }
252: }
