1084:   /**
1085:    * Transforms the promised value by applying the given function to it that returns a promise for the transformed value.
1086:    * <p>
1087:    * This is useful when the transformation involves an asynchronous operation.
1088:    * <pre class="java">{@code
1089:    * import ratpack.test.exec.ExecHarness;
1090:    * import ratpack.exec.ExecResult;
1091:    * import ratpack.exec.Promise;
1092:    * import ratpack.exec.Blocking;
1093:    *
1094:    * import static org.junit.Assert.assertEquals;
1095:    *
1096:    * public class Example {
1097:    *   public static void main(String[] args) throws Exception {
1098:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
1099:    *         Promise.value("foo")
1100:    *           .flatMap(s -> Blocking.get(s::toUpperCase))
1101:    *           .map(s -> s + "-BAR")
1102:    *     );
1103:    *
1104:    *     assertEquals("FOO-BAR", result.getValue());
1105:    *   }
1106:    * }
1107:    * }</pre>
1108:    * <p>
1109:    *
1110:    * @param transformer the transformation to apply to the promised value
1111:    * @param <O> the type of the transformed object
1112:    * @return a promise for the transformed value
1113:    */
1114:   default <O> Promise<O> flatMap(Function<? super T, ? extends Promise<O>> transformer) {
1115:     return transform(up -> down ->
1116:       up.connect(down.<T>onSuccess(value -> {
1117:         try {
1118:           transformer.apply(value).onError(down::error).then(down::success);
1119:         } catch (Throwable e) {
1120:           down.error(e);
1121:         }
1122:       }))
1123:     );
1124:   }
