878:     return transform(up -> down ->
879:       up.connect(down.onError(throwable -> {
880:         if (type.isInstance(throwable)) {
881:           T transformed;
882:           try {
883:             transformed = function.apply(throwable);
884:           } catch (Throwable t) {
885:             down.error(t);
886:             return;
887:           }
888:           down.success(transformed);
889:         } else {
890:           down.error(throwable);
891:         }
892:       }))
893:     );
894:   }
