85:   @SuppressWarnings("deprecation")
86:   private ChannelFuture pre(HttpResponseStatus responseStatus) {
87:     if (transmitted.compareAndSet(false, true)) {
88:       stopTime = Instant.now();
89: 
90:       if (requestBody != null && !requestBody.isComplete()) {
91:         responseHeaders.set(HttpHeaderNames.CONNECTION, HttpHeaderValues.CLOSE);
92:         isKeepAlive = false;
93:       } else if (responseHeaders.contains(HttpHeaderNames.CONNECTION, HttpHeaderValues.CLOSE, true)) {
94:         isKeepAlive = false;
95:       } else if (!isKeepAlive) {
96:         responseHeaders.set(HttpHeaderNames.CONNECTION, HttpHeaderValues.CLOSE);
97:       }
98: 
99:       HttpResponse headersResponse = new CustomHttpResponse(responseStatus, responseHeaders);
100:       if (isKeepAlive && HttpUtil.getContentLength(headersResponse, -1) == -1 && !HttpUtil.isTransferEncodingChunked(headersResponse)) {
101:         HttpUtil.setTransferEncodingChunked(headersResponse, true);
102:       }
