18: 
19: import com.google.common.util.concurrent.AbstractIdleService;
20: import io.netty.bootstrap.ServerBootstrap;
21: import io.netty.channel.Channel;
22: import io.netty.channel.ChannelInitializer;
23: import io.netty.channel.ChannelOption;
24: import io.netty.channel.EventLoopGroup;
25: import io.netty.channel.nio.NioEventLoopGroup;
26: import io.netty.channel.socket.SocketChannel;
27: import io.netty.channel.socket.nio.NioServerSocketChannel;
28: import io.netty.util.concurrent.DefaultThreadFactory;
29: import ratpack.launch.LaunchConfig;
30: 
31: import java.net.InetSocketAddress;
32: import java.util.logging.Level;
33: import java.util.logging.Logger;
34: 
35: public class NettyRatpackService extends AbstractIdleService implements RatpackService {
36: 
37:   private final Logger logger = Logger.getLogger(getClass().getName());
38: 
39:   private final LaunchConfig launchConfig;
40:   private InetSocketAddress boundAddress;
41:   private final ChannelInitializer<SocketChannel> channelInitializerTransformer;
42:   private Channel channel;
43:   private EventLoopGroup group;
44: 
45:   public NettyRatpackService(LaunchConfig launchConfig, ChannelInitializer<SocketChannel> channelInitializer) {
46:     this.launchConfig = launchConfig;
47:     this.channelInitializerTransformer = channelInitializer;
48:   }
49: 
50:   @Override
51:   protected void startUp() throws Exception {
52:     ServerBootstrap bootstrap = new ServerBootstrap();
53:     group = new NioEventLoopGroup(launchConfig.getMainThreads(), new DefaultThreadFactory("ratpack-group", Thread.MAX_PRIORITY));
54: 
55:     bootstrap
56:       .group(group)
57:       .channel(NioServerSocketChannel.class)
58:       .childHandler(channelInitializerTransformer)
59:       .childOption(ChannelOption.ALLOCATOR, launchConfig.getBufferAllocator())
60:       .childOption(ChannelOption.TCP_NODELAY, true)
61:       .option(ChannelOption.SO_REUSEADDR, true)
62:       .option(ChannelOption.SO_BACKLOG, 1024)
63:       .option(ChannelOption.ALLOCATOR, launchConfig.getBufferAllocator());
64: 
65:     try {
66:       channel = bootstrap.bind(buildSocketAddress()).sync().channel();
67:     } catch (Exception e) {
68:       partialShutdown();
69:       throw e;
70:     }
71:     boundAddress = (InetSocketAddress) channel.localAddress();
72: 
73:     if (logger.isLoggable(Level.INFO)) {
74:       logger.info(String.format("Ratpack started for http://%s:%s", getBindHost(), getBindPort()));
75:     }
76:   }
77: 
78:   @Override
79:   protected void shutDown() throws Exception {
80:     channel.close();
81:     partialShutdown();
82:   }
83: 
84:   private void partialShutdown() {
85:     group.shutdownGracefully();
86:     launchConfig.getBackgroundExecutorService().shutdown();
87:   }
88: 
89:   @Override
90:   public String getScheme() {
91:     return launchConfig.getSSLContext() == null ? "http" : "https";
92:   }
93: 
94:   public int getBindPort() {
95:     return boundAddress == null ? -1 : boundAddress.getPort();
96:   }
97: 
98:   public String getBindHost() {
99:     if (boundAddress == null) {
100:       return null;
101:     } else {
102:       return InetSocketAddressBackedBindAddress.determineHost(boundAddress);
103:     }
104:   }
105: 
106:   private InetSocketAddress buildSocketAddress() {
107:     return (launchConfig.getAddress() == null) ? new InetSocketAddress(launchConfig.getPort()) : new InetSocketAddress(launchConfig.getAddress(), launchConfig.getPort());
108:   }
109: 
110: }
