58:             }
59:           }
60:         } else {
61:           Downstream<? super T> downstream = waiting.poll();
62:           while (downstream != null) {
63:             downstream.accept(cached);
64:             downstream = waiting.poll();
65:           }
66:         }
67:       } finally {
68:         draining.set(false);
69:       }
70:     }
71: 
72:     if (!waiting.isEmpty() && (resultRef.get() != null || !pending.get())) {
73:       tryDrain();
74:     }
