17: package ratpack.session.internal;
18: 
19: import io.netty.handler.codec.http.Cookie;
20: import io.netty.handler.codec.http.DefaultCookie;
21: import ratpack.http.Request;
22: import ratpack.http.Response;
23: import ratpack.session.SessionIdCookieConfig;
24: import ratpack.session.SessionIdGenerator;
25: 
26: import java.util.Optional;
27: 
28: public class CookieBasedSessionId implements SessionId {
29: 
30:   private static final String COOKIE_NAME = "JSESSIONID";
31: 
32:   private final Request request;
33:   private final Response response;
34:   private final SessionIdGenerator sessionIdGenerator;
35:   private final SessionIdCookieConfig cookieConfig;
36: 
37:   private String assignedCookieId;
38:   private Optional<String> cookieSessionId;
39: 
40:   public CookieBasedSessionId(Request request, Response response, SessionIdGenerator sessionIdGenerator, SessionIdCookieConfig cookieConfig) {
41:     this.request = request;
42:     this.response = response;
43:     this.sessionIdGenerator = sessionIdGenerator;
44:     this.cookieConfig = cookieConfig;
45:   }
46: 
47:   @Override
48:   public String getValue() {
49:     if (assignedCookieId != null) {
50:       return assignedCookieId;
51:     }
52: 
53:     return getCookieSessionId().orElseGet(() -> {
54:       assignedCookieId = assignId();
55:       return assignedCookieId;
56:     });
57:   }
58: 
59:   private Optional<String> getCookieSessionId() {
60:     if (cookieSessionId == null) {
61:       Cookie match = null;
62: 
63:       for (Cookie cookie : request.getCookies()) {
64:         if (cookie.name().equals(COOKIE_NAME)) {
65:           match = cookie;
66:           break;
67:         }
68:       }
69: 
70:       cookieSessionId = match == null ? Optional.empty() : Optional.of(match.value());
71:     }
72: 
73:     return cookieSessionId;
74:   }
75: 
76:   private String assignId() {
77:     String id = sessionIdGenerator.generateSessionId();
78:     setCookie(id, cookieConfig.getExpiresMins());
79:     return id;
80:   }
81: 
82:   private void setCookie(String value, int expiration) {
83:     DefaultCookie cookie = new DefaultCookie(COOKIE_NAME, value);
84: 
85:     String cookieDomain = cookieConfig.getDomain();
86:     if (cookieDomain != null) {
87:       cookie.setDomain(cookieDomain);
88:     }
89: 
90:     String cookiePath = cookieConfig.getPath();
91:     if (cookiePath != null) {
92:       cookie.setPath(cookiePath);
93:     }
94: 
95:     if (expiration > 0) {
96:       cookie.setMaxAge(expiration * 60);
97:     }
98: 
99:     response.getCookies().add(cookie);
100:   }
101: 
102:   @Override
103:   public void terminate() {
104:     setCookie("", 0);
105:     cookieSessionId = null;
106:     assignedCookieId = null;
107:   }
108: }
