98:       }
99: 
100:       @Override
101:       public void onNext(T t) {
102:         Subscription.this.onNext(t);
103:       }
104: 
105:       @Override
106:       public void onError(Throwable t) {
107:         Subscription.this.onError(t);
108:       }
109: 
110:       @Override
111:       public void onComplete() {
112:         Subscription.this.onComplete();
113:       }
114:     }
