116:     class BufferingSubscriber implements Subscriber<T> {
117:       private final AtomicLong wanted = new AtomicLong(Long.MIN_VALUE);
118:       private final AtomicBoolean open = new AtomicBoolean();
119:       private final ConcurrentLinkedQueue<T> buffer = new ConcurrentLinkedQueue<>();
120:       private final AtomicBoolean draining = new AtomicBoolean();
121: 
122:       @Override
123:       public void onSubscribe(org.reactivestreams.Subscription s) {
