218:   public void next() {
219:     Handler handler = null;
220: 
221:     ChainIndex index = requestConstants.indexes.peek();
222:     while (handler == null) {
223:       if (index.hasNext()) {
224:         handler = index.next();
225:         if (handler.getClass().equals(ChainHandler.class)) {
226:           requestConstants.indexes.push(new ChainIndex(((ChainHandler) handler).getHandlers(), getLaunchConfig(), false));
227:           index = requestConstants.indexes.peek();
228:           handler = null;
229:         }
230:       } else if (index.first) {
231:         handler = requestConstants.applicationConstants.end;
232:       } else {
233:         requestConstants.indexes.pop();
234:         index = requestConstants.indexes.peek();
235:       }
236:     }
237: 
238:     try {
239:       requestConstants.handler = handler;
240:       handler.handle(this);
241:     } catch (Throwable e) {
242:       if (e instanceof HandlerException) {
243:         throw (HandlerException) e;
244:       } else {
245:         throw new HandlerException(e);
