176:   /**
177:    * Creates a failed promise with the given error.
178:    * <p>
179:    * The given error will be used every time that the value is requested.
180:    *
181:    * <pre class="java">{@code
182:    * import ratpack.exec.Promise;
183:    * import ratpack.test.exec.ExecHarness;
184:    *
185:    * import static org.junit.Assert.assertSame;
186:    *
187:    * public class Example {
188:    *   public static void main(String[] args) throws Exception {
189:    *     Exception exception = new Exception();
190:    *     Throwable error = ExecHarness.yieldSingle(e ->
191:    *       Promise.error(exception)
192:    *     ).getThrowable();
193:    *
194:    *     assertSame(exception, error);
195:    *   }
196:    * }
197:    * }</pre>
198:    *
199:    * @param t the error
200:    * @param <T> the type of promised value
201:    * @return a failed promise
202:    * @see #async(Upstream)
203:    * @see #sync(Factory)
204:    * @see #value(Object)
205:    */
206:   static <T> Promise<T> error(Throwable t) {
207:     return async(down -> down.error(t));
208:   }
