930:   /**
931:    * Transforms the promised value by applying the given function to it that returns a promise for the transformed value.
932:    * <p>
933:    * This is useful when the transformation involves an asynchronous operation.
934:    * <pre class="java">{@code
935:    * import ratpack.test.exec.ExecHarness;
936:    * import ratpack.exec.ExecResult;
937:    * import ratpack.exec.Promise;
938:    * import ratpack.exec.Blocking;
939:    *
940:    * import static org.junit.Assert.assertEquals;
941:    *
942:    * public class Example {
943:    *   public static void main(String[] args) throws Exception {
944:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
945:    *         Promise.value("foo")
946:    *           .flatMap(s -> Blocking.get(s::toUpperCase))
947:    *           .map(s -> s + "-BAR")
948:    *     );
949:    *
950:    *     assertEquals("FOO-BAR", result.getValue());
951:    *   }
952:    * }
953:    * }</pre>
954:    * <p>
955:    *
956:    * @param transformer the transformation to apply to the promised value
957:    * @param <O> the type of the transformed object
958:    * @return a promise for the transformed value
959:    */
960:   default <O> Promise<O> flatMap(Function<? super T, ? extends Promise<O>> transformer) {
