1083:   /**
1084:    * Caches the promised value (or error) and returns it to all subscribers.
1085:    * <pre class="java">{@code
1086:    * import ratpack.exec.Promise;
1087:    * import ratpack.test.exec.ExecHarness;
1088:    *
1089:    * import java.util.concurrent.atomic.AtomicLong;
1090:    *
1091:    * import static org.junit.Assert.assertEquals;
1092:    *
1093:    * public class Example {
1094:    *   public static void main(String... args) throws Exception {
1095:    *     ExecHarness.runSingle(c -> {
1096:    *       AtomicLong counter = new AtomicLong();
1097:    *       Promise<Long> uncached = Promise.async(f -> f.success(counter.getAndIncrement()));
1098:    *
1099:    *       uncached.then(i -> assertEquals(0l, i.longValue()));
1100:    *       uncached.then(i -> assertEquals(1l, i.longValue()));
1101:    *       uncached.then(i -> assertEquals(2l, i.longValue()));
1102:    *
1103:    *       Promise<Long> cached = uncached.cache();
1104:    *
1105:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1106:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1107:    *
1108:    *       uncached.then(i -> assertEquals(4l, i.longValue()));
1109:    *       cached.then(i -> assertEquals(3l, i.longValue()));
1110:    *     });
1111:    *   }
1112:    * }
1113:    * }</pre>
1114:    * <p>
1115:    * If the cached promise fails, the same exception will be returned every time.
1116:    * <pre class="java">{@code
1117:    * import ratpack.exec.Promise;
1118:    * import ratpack.test.exec.ExecHarness;
1119:    *
1120:    * import static org.junit.Assert.assertTrue;
