25: import java.util.concurrent.atomic.AtomicBoolean;
26: import java.util.function.Consumer;
27: import java.util.function.Supplier;
28: 
29: public class SafeFulfiller<T> implements Fulfiller<T> {
30: 
31:   private final static Logger LOGGER = LoggerFactory.getLogger(SafeFulfiller.class);
32: 
33:   private final Fulfiller<? super T> delegate;
34:   private final AtomicBoolean fulfilled = new AtomicBoolean();
35:   private final ExecutionBacking streamHandle;
36: 
37:   public SafeFulfiller(ExecutionBacking executionBacking, Fulfiller<? super T> delegate) {
38:     this.streamHandle = executionBacking;
39:     this.delegate = delegate;
40:   }
41: 
42:   public static <T> Consumer<? super Fulfiller<? super T>> wrapping(Supplier<? extends ExecutionBacking> backingSupplier, Action<? super Fulfiller<T>> action) {
43:     return f -> {
44:       ExecutionBacking backing = backingSupplier.get();
45:       SafeFulfiller<T> safe = new SafeFulfiller<>(backing, f);
46:       backing.continueVia(() -> {
47:         try {
48:           action.execute(safe);
49:         } catch (Throwable throwable) {
50:           if (!safe.fulfilled.compareAndSet(false, true)) {
51:             LOGGER.error("", new OverlappingExecutionException("exception thrown after promise was fulfilled", throwable));
52:           } else {
53:             f.error(throwable);
54:           }
55:         }
56:       });
57:     };
58:   }
59: 
60:   @Override
61:   public void error(Throwable throwable) {
62:     if (!fulfilled.compareAndSet(false, true)) {
63:       LOGGER.error("", new OverlappingExecutionException("promise already fulfilled", throwable));
64:       return;
65:     }
66: 
67:     streamHandle.join(e -> delegate.error(throwable));
68:   }
69: 
70:   @Override
71:   public void success(T value) {
72:     if (!fulfilled.compareAndSet(false, true)) {
73:       LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
74:       return;
75:     }
76: 
77:     streamHandle.join(e -> delegate.success(value));
78:   }
79: }
