47:   public DefaultFileHttpTransmitter(FullHttpRequest request, HttpHeaders httpHeaders, Channel channel, boolean compress, long startTime) {
48:     this.request = request;
49:     this.httpHeaders = httpHeaders;
50:     this.channel = channel;
51:     this.compress = compress;
52:     this.startTime = startTime;
53:   }
54: 
55:   private static boolean isNotNullAndStartsWith(String value, String... prefixes) {
56:     if (value == null) {
57:       return false;
58:     }
59:     for (String prefix : prefixes) {
60:       if (value.startsWith(prefix)) {
61:         return true;
62:       }
63:     }
64: 
65:     return false;
66:   }
67: 
68:   @Override
69:   public void transmit(Background execContext, final BasicFileAttributes basicFileAttributes, final Path file) throws Exception {
70:     final boolean compressThis = compress && basicFileAttributes.size() > 1024 && isNotNullAndStartsWith(httpHeaders.get(HttpHeaderConstants.CONTENT_TYPE), "text/", "application/");
71: 
72:     if (compress && !compressThis) {
73:       // Signal to the compressor not to compress this
74:       httpHeaders.set(HttpHeaderConstants.CONTENT_ENCODING, HttpHeaders.Values.IDENTITY);
75:     }
76: 
77:     if (file.getFileSystem().equals(FileSystems.getDefault()) && !compressThis) {
78:       execContext.exec(new Callable<FileChannel>() {
79:         public FileChannel call() throws Exception {
80:           return new FileInputStream(file.toFile()).getChannel();
81:         }
82:       }).then(new Action<FileChannel>() {
83:         public void execute(FileChannel fileChannel) {
84:           FileRegion defaultFileRegion = new DefaultFileRegion(fileChannel, 0, basicFileAttributes.size());
85:           transmit(basicFileAttributes, defaultFileRegion);
86:         }
87:       });
88:     } else {
89:       execContext.exec(new Callable<ReadableByteChannel>() {
90:         public ReadableByteChannel call() throws Exception {
91:           return Files.newByteChannel(file);
92:         }
93:       }).then(new Action<ReadableByteChannel>() {
94:         public void execute(ReadableByteChannel fileChannel) {
95:           transmit(basicFileAttributes, new ChunkedInputAdapter(new ChunkedNioStream(fileChannel)));
96:         }
97:       });
98:     }
99:   }
