101:   private void transmit(BasicFileAttributes basicFileAttributes, final Object message) {
102:     HttpResponse response = new CustomHttpResponse(HttpResponseStatus.OK, httpHeaders);
103:     response.headers().set(HttpHeaderConstants.CONTENT_LENGTH, basicFileAttributes.size());
104: 
105:     if (isKeepAlive(request)) {
106:       response.headers().set(HttpHeaderConstants.CONNECTION, HttpHeaderConstants.KEEP_ALIVE);
107:     }
108: 
109:     request.content().release();
110: 
111:     HttpResponse minimalResponse = new DefaultHttpResponse(response.getProtocolVersion(), response.getStatus());
112:     minimalResponse.headers().set(response.headers());
113:     long stopTime = System.nanoTime();
114: 
115:     if (startTime > 0) {
116:       minimalResponse.headers().set("X-Response-Time", NumberUtil.toMillisDiffString(startTime, stopTime));
117:     }
118: 
119:     ChannelFuture writeFuture = channel.writeAndFlush(minimalResponse);
120: 
121:     writeFuture.addListener(new ChannelFutureListener() {
122:       public void operationComplete(ChannelFuture future) throws Exception {
123:         if (!future.isSuccess()) {
124:           channel.close();
125:         }
126:       }
127:     });
128: 
129:     writeFuture = channel.write(message);
130: 
131:     writeFuture.addListener(new ChannelFutureListener() {
132:       public void operationComplete(ChannelFuture future) {
133:         if (!future.isSuccess()) {
134:           channel.close();
135:         }
136:       }
137:     });
138: 
139:     ChannelFuture lastContentFuture = channel.writeAndFlush(LastHttpContent.EMPTY_LAST_CONTENT);
140:     if (!isKeepAlive(response)) {
141:       lastContentFuture.addListener(ChannelFutureListener.CLOSE);
142:     }
143:   }
144: 
145: }
