536:   @Override
537:   protected void configure() {
538:     SharedMetricRegistries.remove(RATPACK_METRIC_REGISTRY);
539:     MetricRegistry metricRegistry = SharedMetricRegistries.getOrCreate(RATPACK_METRIC_REGISTRY);
540:     bind(MetricRegistry.class).toInstance(metricRegistry);
541: 
542:     bindInterceptor(Matchers.any(), Matchers.annotatedWith(Metered.class), injected(new MeteredMethodInterceptor()));
543:     bindInterceptor(Matchers.any(), Matchers.annotatedWith(Timed.class), injected(new TimedMethodInterceptor()));
544:     bindListener(Matchers.any(), injected(new GaugeTypeListener()));
545: 
546:     bind(JmxReporter.class).toProvider(JmxReporterProvider.class).in(SINGLETON);
547:     bind(ConsoleReporter.class).toProvider(ConsoleReporterProvider.class).in(SINGLETON);
548:     bind(CsvReporter.class).toProvider(CsvReporterProvider.class).in(SINGLETON);
549:     bind(MetricRegistryPeriodicPublisher.class).in(SINGLETON);
550:     bind(MetricsBroadcaster.class).in(SINGLETON);
551:     bind(MetricRegistryJsonMapper.class).in(SINGLETON);
552: 
553:     bind(Startup.class);
554:     Multibinder.newSetBinder(binder(), HandlerDecorator.class).addBinding().toProvider(HandlerDecoratorProvider.class);
555:   }
556: 
557:   private <T> T injected(T instance) {
558:     requestInjection(instance);
559:     return instance;
560:   }
561: 
562:   private static class Startup implements Service {
563: 
564:     private final Config config;
565:     private final Injector injector;
566: 
567:     @Inject
568:     public Startup(Config config, Injector injector) {
569:       this.config = config;
570:       this.injector = injector;
571:     }
572: 
573:     @Override
574:     public void onStart(StartEvent event) throws Exception {
575:       config.getJmx().ifPresent(jmx -> {
576:         if (jmx.isEnabled()) {
577:           injector.getInstance(JmxReporter.class).start();
578:         }
579:       });
580: 
581:       config.getConsole().ifPresent(console -> {
582:         if (console.isEnabled()) {
583:           injector.getInstance(ConsoleReporter.class).start(console.getReporterInterval().getSeconds(), SECONDS);
584:         }
585:       });
586: 
587:       config.getCsv().ifPresent(csv -> {
588:         if (csv.isEnabled()) {
589:           injector.getInstance(CsvReporter.class).start(csv.getReporterInterval().getSeconds(), SECONDS);
590:         }
591:       });
592: 
593:       if (config.isJvmMetrics()) {
594:         final MetricRegistry metricRegistry = injector.getInstance(MetricRegistry.class);
595:         metricRegistry.registerAll(new GarbageCollectorMetricSet());
596:         metricRegistry.registerAll(new ThreadStatesGaugeSet());
597:         metricRegistry.registerAll(new MemoryUsageGaugeSet());
598:       }
599:     }
600:   }
601: 
602:   private static class HandlerDecoratorProvider implements Provider<HandlerDecorator> {
603:     private Config config;
604: 
605:     @Inject
606:     public HandlerDecoratorProvider(Config config) {
607:       this.config = config;
608:     }
609: 
610:     @Override
611:     public HandlerDecorator get() {
612:       return HandlerDecorator.prepend(new RequestTimingHandler(config));
613:     }
614:   }
615: 
616: }
