253:   private void handleAll(Context context) throws Exception {
254:     SortedMap<String, HealthCheck.Result> hcheckResults = new ConcurrentSkipListMap<>();
255: 
256:     SortedMap<String, Promise<HealthCheck.Result>> promises = new ConcurrentSkipListMap<>();
257:     context.getAll(HealthCheck.class).forEach(hcheck -> {
258:       try {
259:         Promise<HealthCheck.Result> promise = hcheck.check(context.getExecution().getControl());
260:         promises.put(hcheck.getName(), promise);
261:       } catch (Exception ex) {
262:         hcheckResults.put(hcheck.getName(), HealthCheck.Result.unhealthy(ex));
263:       }
264:     });
265: 
266:     if (promises.size() == 0) {
267:       context.render(new HealthCheckResults(ImmutableSortedMap.copyOfSorted(hcheckResults)));
268:       return;
269:     }
270: 
271:     context.promise(f -> {
272:       // execute promises in parallel based on the concurrencyLevel
273:       // count finished health checks. If all are done, render results
274:       AtomicInteger executedPromisesCountDown = new AtomicInteger(promises.size());
275:       // count health checks waiting for execution.
276:       AtomicInteger toExecPromisesCountDown = new AtomicInteger(promises.size());
277:       // collect health checks to execute in the next run. Used when concurrencyLevel > 1
278:       Map<String, Promise<HealthCheck.Result>> toExecPromises = new ConcurrentHashMap<>();
279: 
280:       promises.forEach((name, p) -> {
281:         boolean execParallel = false;
282:         if (throttle <= 0) {
283:           // execute all health checks in parallel
284:           execParallel = true;
285:         } else if (throttle == 1) {
286:           // execute promise by promise, in sequence
287:           execParallel = false;
288:         } else {
289:           // collect promises into group of concurrencyLevel size or into group of last promises to execute
290:           toExecPromises.put(name, p);
291:           if (toExecPromisesCountDown.decrementAndGet() > 0 && toExecPromises.size() < throttle) {
292:             return;
293:           }
294:           // execute promises in group in parallel
295:           execParallel = true;
296:         }
297: 
298:         if (toExecPromises.size() > 0) {
299:           // promise of immutable map of promises to execute, controls construction and their parallel execution while allows
300:           // safe freeing of toExecPromises map.
301:           context.promiseOf(ImmutableMap.copyOf(toExecPromises)).then(map -> {
302:             // control finalization of parent promise
303:             AtomicInteger groupOfPromisesCountDown = new AtomicInteger(map.size());
304:             context.promise(f2 -> {
305:               map.forEach((name2, p2) -> {
306:                 // execute promise p2 and check end condition: either last promise in group or last promise globally
307:                 execPromiseWithEndCondition(context, name2, p2, f2, hcheckResults, groupOfPromisesCountDown, executedPromisesCountDown);
308:               });
309:             }).then(finish -> {
310:               if (finish == Boolean.TRUE) {
311:                 f.success(hcheckResults);
312:               }
313:             });
314:           });
315: 
316:           toExecPromises.clear();
317: 
318:         } else {
319:           if (execParallel) {
320:             // execute promise and if last promise globally, return health check results
321:             execPromiseWithEndResult(context, name, p, f, hcheckResults, executedPromisesCountDown);
322:           } else {
323:             context.promise(f2 -> {
324:               // execute promise p and check end condition: if last promise globally
325:               execPromiseWithEndCondition(context, name, p, f2, hcheckResults, null, executedPromisesCountDown);
326:             }).then(finish -> {
327:               if (finish == Boolean.TRUE) {
328:                 f.success(hcheckResults);
329:               }
330:             });
331:           }
332:         }
333:       });
334:     }).then(results -> {
335:       context.render(new HealthCheckResults(ImmutableSortedMap.copyOfSorted(hcheckResults)));
336:     });
337:   }
338: 
339:   private void execPromiseWithEndResult(
340:     Context context,
341:     String name,
342:     Promise<HealthCheck.Result> promise,
343:     Fulfiller<Object> fulfiller,
344:     SortedMap<String, HealthCheck.Result> hcheckResults,
345:     AtomicInteger executedPromisesCountDown) {
346: 
347:     context.exec().onComplete(execution -> {
348:       if (executedPromisesCountDown.decrementAndGet() == 0) {
349:         fulfiller.success(hcheckResults);
350:       }
351:     }).onError(throwable -> {
352:       hcheckResults.put(name, HealthCheck.Result.unhealthy(throwable));
353:       if (executedPromisesCountDown.decrementAndGet() == 0) {
354:         fulfiller.success(hcheckResults);
355:       }
356:     }).start(execution -> {
357:       promise.then(r -> {
358:         hcheckResults.put(name, r);
359:       });
360:     });
361:   }
362: 
363:   private void execPromiseWithEndCondition(
364:     Context context,
365:     String name,
366:     Promise<HealthCheck.Result> promise,
367:     Fulfiller<Object> fulfiller,
368:     SortedMap<String, HealthCheck.Result> hcheckResults,
369:     AtomicInteger groupOfPromisesCountDown, AtomicInteger executedPromisesCountDown) {
370: 
371:     context.exec().onComplete(execution -> {
372:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
373:       if (groupOfPromisesCountDown != null) {
374:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
375:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
376:         }
377:       } else {
378:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
379:       }
380:     }).onError(throwable -> {
381:       hcheckResults.put(name, HealthCheck.Result.unhealthy(throwable));
382:       int i = executedPromisesCountDown != null ? executedPromisesCountDown.decrementAndGet() : 0;
383:       if (groupOfPromisesCountDown != null) {
384:         if (groupOfPromisesCountDown.decrementAndGet() == 0 || i == 0) {
385:           fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
386:         }
387:       } else {
388:         fulfiller.success(i == 0 ? Boolean.TRUE : Boolean.FALSE);
389:       }
390:     }).start(execution -> {
391:       promise.then(r -> {
392:         hcheckResults.put(name, r);
393:       });
394:     });
395:   }
