210:           this.execution.joinExecutionEnd(new Action<ratpack.exec.Execution>() {
211:             @Override
212:             public void execute(ratpack.exec.Execution execution) throws Exception {
213:               subscriber.onComplete();
214:             }
215:           });
216:         }
