231:   public class Execution extends SimpleMutableRegistry implements ratpack.exec.Execution {
232:     private final List<ExecInterceptor> interceptors = new LinkedList<>();
233:     private final Deque<Runnable> segments = new ConcurrentLinkedDeque<>();
234:     private final Queue<Runnable> onCompletes = new ConcurrentLinkedQueue<>();
235: 
236:     private Action<? super Throwable> errorHandler = new Action<Throwable>() {
237:       @Override
238:       public void execute(Throwable throwable) throws Exception {
239:         throw ExceptionUtils.toException(throwable);
240:       }
241:     };
242: 
243:     private final AtomicBoolean active = new AtomicBoolean();
244:     private boolean waiting;
245:     private boolean done;
246: 
247:     public Execution(Action<? super ratpack.exec.Execution> action) {
248:       segments.addLast(new UserCodeSegment(action));
249:       tryDrain();
250:     }
251: 
252:     @Override
253:     public <T> Promise<T> blocking(final Callable<T> operation) {
254:       return control.blocking(operation);
255:     }
256: 
257: 
