263:     @Override
264:     public void fork(Action<? super ratpack.exec.Execution> action) {
265:       control.fork(action);
266:     }
267: 
268:     @Override
269:     public <T> void subscribe(Publisher<T> publisher, Subscriber<T> subscriber) {
270:       control.stream(publisher, subscriber);
271:     }
272: 
273:     @Override
274:     public void setErrorHandler(Action<? super Throwable> errorHandler) {
275:       this.errorHandler = errorHandler;
276:     }
277: 
278:     @Override
279:     public void addInterceptor(ExecInterceptor execInterceptor, Action<? super ratpack.exec.Execution> continuation) throws Exception {
280:       interceptors.add(execInterceptor);
281:       intercept(ExecInterceptor.ExecType.COMPUTE, Collections.singletonList(execInterceptor), continuation);
282:     }
283: 
284:     @Override
285:     public ExecController getController() {
286:       return DefaultExecController.this;
287:     }
288: 
289: 
290:     public void join(final Action<? super ratpack.exec.Execution> action) {
291:       segments.addFirst(new UserCodeSegment(action));
292:       waiting = false;
293:       tryDrain();
294:     }
295: 
296:     public void joinExecutionEnd(final Action<? super ratpack.exec.Execution> action) {
297:       segments.addLast(new UserCodeSegment(action));
298:       waiting = false;
299:       tryDrain();
300:     }
301: 
302:     public void continueExecutionAndWait(final Action<? super ratpack.exec.Execution> action) {
303:       segments.add(new UserCodeSegment(action));
304:       waiting = false;
305:       tryDrain();
306:       waiting = true;
307:     }
308: 
309:     public void continueVia(final Runnable runnable) {
310:       segments.addFirst(new Runnable() {
311:         @Override
312:         public void run() {
313:           waiting = true;
314:           runnable.run();
315:         }
316:       });
317:     }
318: 
319:     private void tryDrain() {
320:       assertNotDone();
321:       if (!done && !waiting && !segments.isEmpty()) {
322:         if (active.compareAndSet(false, true)) {
323:           drain();
324:         }
325:       }
326:     }
327: 
328:     private void runOnCompletes() {
329:       Runnable onComplete = onCompletes.poll();
330:       while (onComplete != null) {
331:         try {
332:           onComplete.run();
333:         } catch (Exception e) {
334:           e.printStackTrace();
335:         } finally {
336:           onComplete = onCompletes.poll();
337:         }
338:       }
339:     }
340: 
341:     private void drain() {
342:       if (isManagedThread()) {
343:         executionHolder.set(this);
344:         try {
345:           Runnable segment = segments.poll();
346:           while (segment != null) {
347:             segment.run();
348:             if (waiting) { // the segment initiated an async op
349:               break;
350:             } else {
351:               segment = segments.poll();
352:               if (segment == null) { // not waiting and no more segments, we are done
353:                 done = true;
354:                 runOnCompletes();
355:               }
356:             }
357:           }
358:         } finally {
359:           executionHolder.remove();
360:           active.set(false);
361:         }
362:         if (waiting) {
363:           tryDrain();
364:         }
365:       } else {
366:         active.set(false);
367:         eventLoopGroup.submit(new Runnable() {
368:           @Override
369:           public void run() {
370:             tryDrain();
371:           }
372:         });
373:       }
374:     }
375: 
376:     @Override
377:     public void onComplete(Runnable runnable) {
378:       assertNotDone();
379:       onCompletes.add(runnable);
380:     }
381: 
382:     private void assertNotDone() {
383:       if (done) {
384:         throw new ExecutionException("execution is complete");
385:       }
386:     }
387: 
388:     public void intercept(final ExecInterceptor.ExecType execType, final List<ExecInterceptor> interceptors, final Action<? super Execution> action) throws Exception {
389:       new InterceptedOperation(execType, interceptors) {
390:         @Override
391:         protected void performOperation() throws Exception {
392:           action.execute(Execution.this);
393:         }
394:       }.run();
395:     }
396: 
397:     /**
398:      * An execution segment that executes “user code” (i.e. not execution management infrastructure)
399:      */
400:     private class UserCodeSegment implements Runnable {
401:       private final Action<? super ratpack.exec.Execution> action;
402: 
403:       public UserCodeSegment(Action<? super ratpack.exec.Execution> action) {
404:         this.action = action;
405:       }
406: 
407:       @Override
408:       public void run() {
409:         try {
410:           try {
411:             intercept(ExecInterceptor.ExecType.COMPUTE, interceptors, action);
412:           } catch (ExecutionSegmentTerminationError e) {
413:             throw e.getCause();
414:           }
415:         } catch (final Throwable e) {
416:           segments.clear();
417:           segments.addFirst(new Runnable() {
418:             @Override
419:             public void run() {
420:               try {
421:                 errorHandler.execute(e);
422:               } catch (final Throwable e) {
423:                 segments.addFirst(new UserCodeSegment(new Action<ratpack.exec.Execution>() {
424:                   @Override
425:                   public void execute(ratpack.exec.Execution execution) throws Exception {
426:                     throw e;
427:                   }
428:                 }));
429:               }
430:             }
431:           });
432:         }
433:       }
434:     }
435:   }
436: 
437:   @Override
438:   public ExecControl getControl() {
439:     return control;
440:   }
