442:   private class ExecControllerBindingThreadFactory extends DefaultThreadFactory {
443:     public ExecControllerBindingThreadFactory(String name, int priority) {
444:       super(name, priority);
445:     }
446: 
447:     @Override
448:     public Thread newThread(final Runnable r) {
449:       return super.newThread(new Runnable() {
450:         @Override
451:         public void run() {
452:           THREAD_BINDING.set(DefaultExecController.this);
453:           r.run();
454:         }
455:       });
456:     }
457: 
458:   }
459: 
460:   @Override
461:   public boolean isManagedThread() {
462:     Optional<ExecController> threadBoundController = getThreadBoundController();
463:     return threadBoundController.isPresent() && threadBoundController.get() == this;
464:   }
465: 
466:   @Override
467:   public int getNumThreads() {
468:     return numThreads;
469:   }
470: 
471: }
