146:    */
147:   public void setWorkerThreads(int workerThreads) {
148:     this.workerThreads = workerThreads;
149:   }
150: 
151:   /**
152:    * Constructs a new server based on the builder's state.
153:    *
154:    * The returned server has not been started.
155:    *
156:    * @return A new, not yet started, Ratpack server.
157:    */
