159:     InetSocketAddress address = buildSocketAddress();
160:     ChannelInitializer<SocketChannel> channelInitializer = buildChannelInitializer();
161:     return new NettyRatpackServer(
162:         address, channelInitializer, init
163:     );
164:   }
