31: /**
32:  * Builds a {@link RatpackServer}.
33:  */
34: public class RatpackServerBuilder {
35: 
36:   /**
37:    * The port that Ratpack apps use unless otherwise specified ({@value}).
38:    */
39:   public static final int DEFAULT_PORT = 5050;
40: 
41:   private final Handler handler;
42:   private final File baseDir;
43: 
44:   private int workerThreads = Runtime.getRuntime().availableProcessors() * 2;
45: 
46:   private int port = DEFAULT_PORT;
47:   private String socketAddress;
48:   private Action<RatpackServer> init = new NoopInit();
49: 
50:   /**
51:    * Create a new builder, with the given handler as the "application".
52:    *
53:    * @param handler The handler for all requests.
54:    * @param baseDir The directory that will serve as the initial {@link org.ratpackframework.file.FileSystemBinding} for all handlers
55:    */
56:   public RatpackServerBuilder(Handler handler, File baseDir) {
57:     this.handler = handler;
58:     this.baseDir = baseDir;
59:   }
60: 
61:   /**
62:    * The port that the application should listen to requests on.
63:    *
64:    * Defaults to {@value #DEFAULT_PORT}.
65:    *
66:    * @return The port that the application should listen to requests on.
67:    */
68:   public int getPort() {
69:     return port;
70:   }
71: 
72:   /**
73:    * Sets the port that the application should listen to requests on.
74:    *
75:    * @param port The port.
76:    */
77:   public void setPort(int port) {
78:     this.port = port;
79:   }
80: 
81:   /**
82:    * The hostname of the interface that the application should bind to.
83:    *
84:    * A value of null causes all interfaces to be bound. Defaults to null.
85:    *
86:    * @return The hostname of the interface that the application should bind to.
87:    */
88:   @Nullable
89:   public String getAddress() {
90:     return socketAddress;
91:   }
92: 
93:   /**
94:    * Sets the hostname of the interface that the application should bind to.
95:    *
96:    * A value of null causes all interfaces to be bound.
97:    *
98:    * @param host The host.
99:    */
100:   public void setHost(@Nullable String host) {
101:     this.socketAddress = host;
102:   }
103: 
104:   /**
105:    * The action that will be executed with the server when it is started.
106:    *
107:    * Defaults to a noop.
108:    *
109:    * @return The action that will be executed with the server when it is started.
110:    */
111:   public Action<RatpackServer> getInit() {
112:     return init;
113:   }
114: 
115:   /**
116:    * Sets the action that will be executed with the server when it is started.
117:    *
118:    * @param init The action that to execute with the server when it is started.
119:    */
120:   public void setInit(Action<RatpackServer> init) {
121:     this.init = init;
122:   }
123: 
124:   /**
125:    * The number of worker threads for handling application requests.
126:    *
127:    * If the value is greater than 0, a thread pool (of this size) will be created for servicing requests. This allows handlers
128:    * to perform blocking operations.
129:    * <p>
130:    * If the value is 0 or less, no thread pool will be used to handle requests. This means that the handler will be called on the
131:    * same thread that accepted the request. This means that handlers SHOULD NOT block in their operation.
132:    * <p>
133:    * The default value for this property is calculated as: {@code Runtime.getRuntime().availableProcessors() * 2}
134:    *
135:    * @return The number of worker threads to use to execute the handler.
136:    */
137:   public int getWorkerThreads() {
138:     return workerThreads;
139:   }
140: 
141:   /**
142:    * Sets the number of worker threads to use to execute the handler.
143:    *
144:    * @see #setWorkerThreads(int)
145:    * @param workerThreads The number of worker threads to use to execute the handler.
146:    */
147:   public void setWorkerThreads(int workerThreads) {
148:     this.workerThreads = workerThreads;
149:   }
150: 
151:   /**
152:    * Constructs a new server based on the builder's state.
153:    *
154:    * The returned server has not been started.
155:    *
156:    * @return A new, not yet started, Ratpack server.
157:    */
158:   public RatpackServer build() {
159:     InetSocketAddress address = buildSocketAddress();
160:     ChannelInitializer<SocketChannel> channelInitializer = buildChannelInitializer();
161:     return new NettyRatpackServer(
162:         address, channelInitializer, init
163:     );
164:   }
165: 
166:   private InetSocketAddress buildSocketAddress() {
167:     return (socketAddress == null) ? new InetSocketAddress(port) : new InetSocketAddress(socketAddress, port);
168:   }
169: 
170:   private ChannelInitializer<SocketChannel> buildChannelInitializer() {
171:     return new RatpackChannelInitializer(workerThreads, handler, baseDir);
172:   }
173: 
174: }
