17: package ratpack.pac4j;
18: 
19: import org.pac4j.core.client.Client;
20: import org.pac4j.core.credentials.Credentials;
21: import org.pac4j.core.profile.UserProfile;
22: import ratpack.handling.Context;
23: import ratpack.pac4j.internal.Pac4jCallbackHandler;
24: import ratpack.pac4j.internal.RatpackWebContext;
25: 
26: import java.util.function.BiConsumer;
27: import java.util.function.BiFunction;
28: 
29: /**
30:  * Builder for Pac4J callback handler.
31:  */
32: public class Pac4jCallbackHandlerBuilder {
33: 
34:   private BiFunction<Context, RatpackWebContext, Client<Credentials, UserProfile>> onFindClient;
35:   private BiConsumer<Context, UserProfile> onProfile;
36:   private BiConsumer<Context, Throwable> onError;
37: 
38:   public Pac4jCallbackHandler build() {
39:     return new Pac4jCallbackHandler(onFindClient, onProfile, onError);
40:   }
41: 
42:   /**
43:    * Add function for looking up client given the context.
44:    *
45:    * <p>e.g.</p>
46:    * <pre>
47:    * <code>
48:    * builder.findClient(((context, ratpackContext) -&gt; context.getRequest().get(Clients.class).findClient(context.getPathTokens().get("clientName"))
49:    * </code>
50:    * </pre>
51:    *
52:    * @param findClientFunction the lookup function
53:    * @return the builder
54:    */
55:   @SuppressWarnings("unused")
56:   public Pac4jCallbackHandlerBuilder findClient(BiFunction<Context, RatpackWebContext, Client<Credentials, UserProfile>> findClientFunction) {
57:     this.onFindClient = findClientFunction;
58:     return this;
59:   }
60: 
61:   /**
62:    * Add handler for dealing with the newly-looked-up profile
63:    *
64:    * <p>e.g.</p>
65:    * <pre>
66:    * <code>
67:    * builder.handleProfile(((context, profile) -&gt; context.next(Registries.just(profile))));
68:    * </code>
69:    * </pre>
70:    *
71:    * @param onError the handler function
72:    * @return the builder
73:    */
74:   @SuppressWarnings("unused")
75:   public Pac4jCallbackHandlerBuilder handleProfile(BiConsumer<Context, UserProfile> onError) {
76:     this.onProfile = onError;
77:     return this;
78:   }
79: 
80:   /**
81:    * Add handler for dealing with errors
82:    *
83:    * <p>e.g.</p>
84:    * <pre>
85:    * <code>
86:    * this.handleError((context, ex) -&gt; {
87:    *     LOGGER.error("Error logging in", ex);
88:    *     context.redirect("/some/url");
89:    * });
90:    * </code>
91:    * </pre>
92:    *
93:    * @param handleErrorFunction the handler function
94:    * @return the builder
95:    */
96:   @SuppressWarnings("unused")
97:   public Pac4jCallbackHandlerBuilder handleError(BiConsumer<Context, Throwable> handleErrorFunction) {
98:     this.onError = handleErrorFunction;
99:     return this;
100:   }
101: 
102: }
