192:   /**
193:    * Converts a {@link Promise} for an iterable into an {@link Observable}.
194:    * <p>
195:    * The promised iterable will be emitted to the observer one element at a time, like {@link Observable#fromIterable(Iterable)}.
196:    * <p>
197:    * <pre class="java">{@code
198:    * import ratpack.rx2.RxRatpack;
199:    * import ratpack.exec.Promise;
200:    * import ratpack.test.exec.ExecHarness;
201:    *
202:    * import java.util.Arrays;
203:    * import java.util.LinkedList;
204:    * import java.util.List;
205:    *
206:    * import static org.junit.Assert.assertEquals;
207:    *
208:    * public class Example {
209:    *   public static void main(String... args) throws Exception {
210:    *     final List<String> items = new LinkedList<>();
211:    *     ExecHarness.runSingle(e ->
212:    *       Promise.value(Arrays.asList("foo", "bar"))
213:    *         .to(RxRatpack::observeEach)
214:    *         .subscribe(items::add)
215:    *     );
216:    *
217:    *     assertEquals(Arrays.asList("foo", "bar"), items);
218:    *   }
219:    * }
220:    * }</pre>
221:    *
222:    * @param promise the promise
223:    * @param <T>     the element type of the promised iterable
224:    * @param <I>     the type of iterable
225:    * @return an observable for each element of the promised iterable
226:    * @see #observe(ratpack.exec.Promise)
227:    */
228:   public static <T, I extends Iterable<T>> Observable<T> observeEach(Promise<I> promise) {
229:     return Observable.merge(observe(promise).map(Observable::fromIterable));
230:   }
