332:    * import java.util.List;
333:    * import java.util.Arrays;
334:    * import static org.junit.Assert.assertEquals;
335:    *
336:    * public class Example {
337:    *   public static class AsyncService {
338:    *     public <T> Observable<T> observe(final T value) {
339:    *       return Observable.create(subscriber ->
340:    *         new Thread(() -> {
341:    *           subscriber.onNext(value);
342:    *           subscriber.onComplete();
343:    *         }).start()
344:    *       );
345:    *     }
346:    *   }
347:    *
348:    *   public static void main(String[] args) throws Throwable {
349:    *     List<String> results = ExecHarness.yieldSingle(execution ->
350:    *       RxRatpack.promise(new AsyncService().observe("foo"))
351:    *     ).getValue();
352:    *
353:    *     assertEquals(Arrays.asList("foo"), results);
354:    *   }
355:    * }
356:    * }</pre>
