378:    * Converts an {@link Observable} into a {@link Promise}, for all of the observable's items.
379:    * <p>
380:    * This method can be used to simply adapt an observable to a promise, but can also be used to bind an observable to the current execution.
381:    * <p>
382:    * <pre class="java">{@code
383:    * import ratpack.rx2.RxRatpack;
384:    * import ratpack.test.exec.ExecHarness;
385:    * import io.reactivex.Observable;
386:    * import java.util.List;
387:    * import java.util.Arrays;
388:    *
389:    * import static org.junit.Assert.assertEquals;
390:    *
391:    * public class Example {
392:    *   public static class AsyncService {
393:    *     public <T> Observable<T> observe(final T value) {
394:    *       return Observable.create(subscriber ->
395:    *         new Thread(() -> {
396:    *           subscriber.onNext(value);
397:    *           subscriber.onComplete();
398:    *         }).start()
399:    *       );
400:    *     }
401:    *   }
402:    *
403:    *   public static void main(String[] args) throws Throwable {
404:    *     List<String> results = ExecHarness.yieldSingle(execution ->
405:    *       new AsyncService().observe("foo").as(RxRatpack::promise)
406:    *     ).getValue();
407:    *
408:    *     assertEquals(Arrays.asList("foo"), results);
409:    *   }
410:    * }
411:    * }</pre>
412:    * <p>
413:    * <p>
414:    * This method uses {@link Observable#toList()} to collect the observable's contents into a list.
415:    * It therefore should not be used with observables with many or infinite items.
416:    * <p>
417:    * If it is expected that the observable only emits one element, it is typically more convenient to use {@link #promiseSingle(Observable)}.
418:    * <p>
419:    * If the observable emits an error, the returned promise will fail with that error.
420:    * <p>
421:    * This method must be called during an execution.
422:    *
423:    * @param onSubscribe the on subscribe function
424:    * @param <T>         the type of the value observed
425:    * @return a promise that returns all values from the observable
426:    * @throws UnmanagedThreadException if called outside of an execution
427:    * @see #promiseSingle(Observable)
428:    * @see #promiseAll(Observable)
429:    */
