434:   /**
435:    * Converts an {@link Observable} into a {@link Promise}, for the observable's single item.
436:    * <p>
437:    * This method can be used to simply adapt an observable to a promise, but can also be used to bind an observable to the current execution.
438:    * It is sometimes more convenient to use {@link #promiseSingle(ObservableOnSubscribe)} over this method.
439:    * <p>
440:    * <pre class="java">{@code
441:    * import ratpack.rx2.RxRatpack;
442:    * import ratpack.test.exec.ExecHarness;
443:    * import io.reactivex.Observable;
444:    *
445:    * import static org.junit.Assert.assertEquals;
446:    *
447:    * public class Example {
448:    *   public static class AsyncService {
449:    *     public <T> Observable<T> observe(final T value) {
450:    *       return Observable.create(subscriber ->
451:    *         new Thread(() -> {
452:    *           subscriber.onNext(value);
453:    *           subscriber.onComplete();
454:    *         }).start()
455:    *       );
456:    *     }
457:    *   }
458:    *
459:    *   public static void main(String[] args) throws Throwable {
460:    *     String result = ExecHarness.yieldSingle(execution ->
461:    *       RxRatpack.promiseSingle(new AsyncService().observe("foo"))
462:    *     ).getValue();
463:    *
464:    *   assertEquals("foo", result);
465:    *   }
466:    * }
467:    * }</pre>
468:    * <p>
469:    * This method uses {@link Observable#singleElement()} to enforce that the observable only emits one item.
470:    * If the observable may be empty, then use {@link Observable#single(Object)} to provide a default value.
471:    * <p>
472:    * <pre class="java">{@code
473:    * import ratpack.rx2.RxRatpack;
474:    * import ratpack.test.exec.ExecHarness;
475:    * import io.reactivex.Observable;
476:    *
477:    * import static org.junit.Assert.assertEquals;
478:    *
479:    * public class Example {
480:    *   public static void main(String[] args) throws Throwable {
481:    *     String result = ExecHarness.yieldSingle(execution ->
482:    *       RxRatpack.promiseSingle(Observable.<String>empty().single("foo"))
483:    *     ).getValue();
484:    *     assertEquals("foo", result);
485:    *   }
486:    * }
487:    * }</pre>
488:    * <p>
489:    * If it is expected that the observable may emit more than one element, use {@link #promiseAll(Observable)}.
490:    * <p>
491:    * If the observable emits an error, the returned promise will fail with that error.
492:    * If the observable emits no items, the returned promise will fail with a {@link java.util.NoSuchElementException}.
493:    * If the observable emits more than one item, the returned promise will fail with an {@link IllegalStateException}.
494:    * <p>
495:    * This method must be called during an execution.
496:    *
497:    * @param observable the observable
498:    * @param <T>        the type of the value observed
499:    * @return a promise that returns the sole value from the observable
500:    * @see #promiseAll(Observable)
501:    * @see #promiseSingle(ObservableOnSubscribe)
502:    */
503:   public static <T> Promise<T> promiseSingle(Observable<T> observable) throws UnmanagedThreadException {
504:     return Promise.async(f -> observable.singleElement().subscribe(f::success, f::error));
505:   }
506: 
