510:    * @return
511:    * @throws UnmanagedThreadException
512:    * @see RxRatpack#promiseSingle(Observable)
513:    */
514:   public static <T> Promise<T> promiseSingle(Single<T> single) throws UnmanagedThreadException {
515:     return Promise.async(f -> single.subscribe(f::success, f::error));
516:   }
