540:    *
541:    * public class Example {
542:    *   public static class AsyncService {
543:    *     public <T> Observable<T> observe(final T value) {
544:    *       return Observable.create(subscriber ->
545:    *         new Thread(() -> {
546:    *           subscriber.onNext(value);
547:    *           subscriber.onComplete();
548:    *         }).start()
549:    *       );
550:    *     }
551:    *   }
552:    *
553:    *   public static void main(String[] args) throws Throwable {
554:    *     String result = ExecHarness.yieldSingle(execution ->
555:    *       new AsyncService().observe("foo").as(RxRatpack::promiseSingle)
556:    *     ).getValue();
557:    *
558:    *     assertEquals("foo", result);
559:    *   }
560:    * }
561:    * }</pre>
562:    * <p>
563:    * This method uses {@link Observable#singleElement()} to enforce that the observable only emits one item.
564:    * If the observable may be empty, then use {@link Observable#single(Object)} to provide a default value.
565:    * <pre class="java">{@code
566:    * import ratpack.rx2.RxRatpack;
567:    * import ratpack.test.exec.ExecHarness;
568:    * import io.reactivex.Observable;
569:    *
570:    * import static org.junit.Assert.assertEquals;
